```

### Step 3: Export getPendingChart from agent.ts

Add a new exported function:
```typescript
export function getPendingChart(userId: number): Buffer | undefined {
  const state = sessions.get(userId);
  if (state?.pendingChart) {
    const chart = state.pendingChart;
    state.pendingChart = undefined;  // consume it (one-time use)
    return chart;
  }
  return undefined;
}
```

